import os
import warnings
import configparser


def get_config_from_root():
    """Find and read the toolz configuration file from the filesystem root.

    This function searches for a configuration file named ``toolz.cfg``
    starting from the current working directory and moving up to the
    filesystem root.  If no such file is found, it returns an empty
    dictionary.

    If the configuration file exists but cannot be read or parsed, a
    warning is emitted describing the problem.

    Returns
    -------
    config : dict
        A dictionary of configuration values.  Returns an empty dict if
        no configuration file is found.

    Warnings
    --------
    warnings.UserWarning
        If a configuration file exists but is malformed or unreadable.
    """
    path = os.path.abspath(os.getcwd())
    while True:
        cfg_path = os.path.join(path, 'toolz.cfg')
        if os.path.isfile(cfg_path):
            config = configparser.ConfigParser()
            try:
                config.read(cfg_path)
            except configparser.Error as e:
                warnings.warn(
                    "Configuration file {} contains errors: {}".format(
                        cfg_path, str(e)),
                    stacklevel=2,
                )
                return {}
            try:
                return {s: dict(config.items(s)) for s in config.sections()}
            except configparser.Error as e:
                warnings.warn(
                    "Could not parse configuration file {}: {}".format(
                        cfg_path, str(e)),
                    stacklevel=2,
                )
                return {}
        parent = os.path.dirname(path)
        if parent == path:
            # Reached the root
            return {}
        path = parent


def raises(err, lamda):
    try:
        lamda()
        return False
    except err:
        return True


